            <form v-if="editingRecordingId !== null" class="edit-recording-form" @submit.prevent="saveRecordingMetadata">
              <div class="section-heading">
                <div><p class="eyebrow">EDITAR REGISTRO</p><h3>Datos de la audición</h3></div>
