              <label>Canción
                <input v-model.trim="editForm.song" class="field" maxlength="160" placeholder="Nombre de la canción" />
              </label>
              <div class="form-actions">
                <button class="primary" type="submit" :disabled="busy">{{ busy ? 'Guardando…' : 'Guardar cambios' }}</button>
              </div>
              <p class="muted">Esto modifica los metadatos, no el audio ni el análisis existente. Para repetir el análisis con una grabación nueva, elimina esta audición y crea otra.</p>
            </form>
          </section>

          <template v-if="activeRecording">
            <section class="panel">
              <div class="section-heading"><div><p class="eyebrow">EVIDENCIA DEL MOTOR</p><h2>{{ activeRecording.title || 'Análisis AMV' }}</h2></div><span class="status" :class="analysisStatus?.tone === 'done' ? 'done' : 'pending'">{{ analysisStatus?.title || 'Sin resultado visible' }}</span></div>
              <p class="muted">Las mediciones automáticas se conservan como evidencia independiente. No reemplazan la pauta docente ni generan por sí solas un diagnóstico vocal.</p>
              <div v-if="analysisStatus" class="analysis-state" :class="analysisStatus.tone">
                <span class="state-dot"></span>
                <div><strong>{{ analysisStatus.title }}</strong><p>{{ analysisStatus.description }}</p></div>
              </div>
              <p v-else class="muted">El análisis se solicita automáticamente al registrar una nueva audición. Esta pantalla consulta el estado y muestra el resultado guardado; no vuelve a ejecutar el worker.</p>
              <div v-if="acousticMetrics" class="acoustic-metrics" aria-label="Métricas acústicas disponibles">
                <div class="acoustic-metric">
                  <span>Afinación de referencia</span>
                  <strong>{{ formatPercent(acousticMetrics.intonation) }}</strong>
                  <small>Porcentaje calculado por AMV</small>
                </div>
                <div class="acoustic-metric">
                  <span>Precisión melódica</span>
                  <strong>{{ formatPercent(acousticMetrics.melodicAccuracy) }}</strong>
                  <small>Eventos dentro de ±100 cents</small>
                </div>
                <div class="acoustic-metric">
                  <span>Dentro de ±25 cents</span>
                  <strong>{{ formatPercent(acousticMetrics.within25) }}</strong>
                </div>
                <div class="acoustic-metric">
                  <span>Dentro de ±50 cents</span>
                  <strong>{{ formatPercent(acousticMetrics.within50) }}</strong>
                </div>
                <div class="acoustic-metric">
                  <span>Dentro de ±100 cents</span>
                  <strong>{{ formatPercent(acousticMetrics.within100) }}</strong>
                </div>
                <div class="acoustic-metric">
                  <span>Eventos comparados</span>
                  <strong>{{ acousticMetrics.matchedEvents ?? '—' }}</strong>
                  <small v-if="acousticMetrics.excludedOctaves != null">{{ acousticMetrics.excludedOctaves }} eventos de octava excluidos de la afinación</small>
                </div>
                <p class="acoustic-disclaimer">Estas son métricas técnicas expresadas en porcentajes. Se muestran como evidencia independiente y no se convierten automáticamente en notas de 1 a 10 ni se mezclan con la pauta docente.</p>
              </div>
              <details v-if="activeRecording.analysis" class="technical-details">
                <summary>Ver detalle técnico del análisis</summary>
                <pre class="analysis-json">{{ JSON.stringify(activeRecording.analysis.workerResult || activeRecording.analysis.worker_result || activeRecording.analysis, null, 2) }}</pre>
              </details>
              <div class="form-actions">
                <button class="secondary" :disabled="busy" @click="refreshAnalysisStatus">{{ busy ? 'Actualizando…' : 'Actualizar estado' }}</button>
                <span class="muted">Actualizar consulta el resultado guardado; no crea ni reencola trabajos.</span>
              </div>
            </section>

            <section class="panel media-panel">
              <div class="section-heading">
                <div><p class="eyebrow">AUDICIÓN SELECCIONADA</p><h2>Escuchar interpretación</h2></div>
                <span class="status" :class="activeRecording.audioUrl ? 'done' : 'pending'">{{ activeRecording.audioUrl ? 'Audio disponible' : 'Audio no localizado' }}</span>
              </div>
              <p class="muted">Escucha la grabación original antes de puntuar. La reproducción depende de que el archivo esté disponible en el almacenamiento de AMV.</p>
              <audio v-if="activeRecording.audioUrl" class="audio-player" controls preload="metadata" :src="activeRecording.audioUrl">
                Tu navegador no permite reproducir este audio.
              </audio>
              <div v-else class="audio-unavailable">
                <strong>No hay una URL de audio disponible para esta audición.</strong>
                <p>Comprueba que el registro tenga <code>storagePath</code> y que el bucket permita crear una URL firmada.</p>
                <button class="secondary" type="button" :disabled="loadingAudio" @click="loadActiveAudio">{{ loadingAudio ? 'Buscando audio…' : 'Volver a buscar audio' }}</button>
              </div>
            </section>

            <section class="panel chart-panel">
              <div class="section-heading">
                <div><p class="eyebrow">PERFIL DE OCHO DIMENSIONES</p><h2>Gráfica de evaluación vocal</h2></div>
                <span class="step">ESCALA INTEGRAL 1–10</span>
              </div>
              <p class="muted">Escala 1–10. Afinación y ritmo pueden combinar 50 % docente + 50 % AMV cuando hay una nota automática explícita y válida. Las otras seis dimensiones se evalúan con criterio docente; una métrica ausente nunca se inventa.</p>
              <div class="integral-banner" :class="integratedStatus">
                <strong>{{ integratedStatus === 'complete' ? 'Evaluación integral completa' : integratedStatus === 'partial' ? 'Evaluación integral parcial' : 'Evaluación pendiente' }}</strong>
                <span>{{ integratedStatus === 'complete' ? `Pauta docente completa. ${acousticScores.intonation != null ? 'Afinación combina ambas fuentes.' : 'Afinación usa la nota docente si AMV no entrega una nota válida.'} ${acousticScores.rhythm != null ? 'Ritmo combina ambas fuentes.' : 'Ritmo usa la nota docente si AMV no entrega una nota válida.'}` : integratedStatus === 'partial' ? 'Pauta docente incompleta: las dimensiones sin nota docente pueden mostrar solo una puntuación AMV válida. Completa las ocho dimensiones para cerrar la evaluación.' : 'Completa la pauta docente para obtener una evaluación.' }}</span>
                <b>{{ integratedAverage }}</b><small>/10</small>
              </div>
              <div class="radar-wrap">
                <svg class="radar-chart" viewBox="0 0 460 390" role="img" aria-label="Gráfica radial de la evaluación integral AMV en escala de 1 a 10">
                  <g v-for="level in [2,4,6,8,10]" :key="'grid-'+level">
                    <polygon :points="integratedRadarGrid(level)" class="radar-grid" />
                    <text :x="230" :y="194 - level * 15.5" class="radar-tick">{{ level }}</text>
                  </g>
                  <g v-for="(dimension, index) in dimensions" :key="'axis-'+dimension.key">
                    <line x1="230" y1="194" :x2="integratedRadarPoint(index, 10).x" :y2="integratedRadarPoint(index, 10).y" class="radar-axis" />
                    <text :x="radarLabel(index).x" :y="radarLabel(index).y" :text-anchor="radarLabel(index).anchor" class="radar-label">{{ shortDimensionLabel(dimension.label) }}</text>
                  </g>
                  <polygon v-if="integratedDimensionsCount > 0" :points="integratedRadarPolygon" class="radar-score-area" />
                  <g v-if="integratedDimensionsCount > 0">
                    <circle v-for="dimension in dimensions.filter(d => integratedScores[d.key] != null)" :key="'point-'+dimension.key" :cx="integratedRadarPoint(dimensions.findIndex(d => d.key === dimension.key), integratedScores[dimension.key]).x" :cy="integratedRadarPoint(dimensions.findIndex(d => d.key === dimension.key), integratedScores[dimension.key]).y" r="4.5" class="radar-point" />
                  </g>
                </svg>
              </div>
              <div class="chart-legend"><span><i></i> Evaluación integral AMV</span><span>{{ integratedDimensionsCount }}/8 dimensiones con puntuación disponible</span></div>
            </section>

            <section class="panel">
              <div class="section-heading"><div><p class="eyebrow">PAUTA PEDAGÓGICA</p><h2>Tu evaluación docente</h2></div><span class="step">OCHO DIMENSIONES</span></div>
              <p class="muted">Evalúa cada dimensión de 1 a 10 según la pauta pedagógica. 1 = requiere trabajo prioritario; 10 = desempeño sólido observado. No dejes dimensiones sin evaluar.</p>
              <div class="proposal-toolbar">
                <div><strong>Asistente pedagógico</strong><p>Genera un borrador a partir de tus ocho puntuaciones. Revisa y edita cada campo antes de guardar.</p></div>
                <button class="secondary" type="button" :disabled="completedDimensions !== 8" @click="generatePedagogicalProposal">✦ Generar propuesta</button>
              </div>
              <p v-if="proposalMessage" class="proposal-message" role="status">{{ proposalMessage }}</p>
              <form @submit.prevent="saveEvaluation">
                <div class="dimension-grid">
                  <article v-for="dimension in dimensions" :key="dimension.key" class="dimension-card">
                    <div><h3>{{ dimension.label }}</h3><p>{{ dimension.prompt }}</p></div>
                    <div class="rating-row" role="group" :aria-label="`Puntuación docente: ${dimension.label}`">
                      <button v-for="n in 10" :key="n" type="button" class="rating" :class="{ chosen: Number(scores[dimension.key]) === n }" :aria-pressed="Number(scores[dimension.key]) === n" @click="setScore(dimension.key, n)">{{ n }}</button>
                    </div>
                  </article>
                </div>
                <div class="form-grid">
                  <label>Fortalezas observadas<textarea v-model.trim="strengths" class="field" rows="3" placeholder="¿Qué hizo bien? ¿Qué conviene mantener?" /></label>
                  <label>Prioridades de trabajo<textarea v-model.trim="priorities" class="field" rows="3" placeholder="¿Qué necesita trabajar primero y por qué?" /></label>
                  <label class="wide">Observaciones del profesor<textarea v-model.trim="observations" class="field" rows="3" placeholder="Evidencia escuchada, contexto, matices o discrepancias con AMV." /></label>
                  <label class="wide">Plan de ejercicios para la próxima clase<textarea v-model.trim="exercisePlan" class="field" rows="4" placeholder="Ejercicio, instrucciones, duración/repeticiones y criterio de logro. Fundamentar en las fuentes de estudio AMV." /></label>
                </div>
                <div class="form-actions">
                  <button class="primary" :disabled="busy" type="submit">{{ busy ? 'Guardando…' : 'Guardar evaluación docente' }}</button>
                  <span class="muted">La evaluación queda vinculada a esta audición.</span>
                </div>
              </form>
            </section>

            <section class="panel">
              <p class="eyebrow">SÍNTESIS ACTUAL</p>
              <h2>Evaluación integral y siguiente paso</h2>
              <p class="muted">Solo afinación y ritmo admiten combinación automática. La nota integral es el promedio de las puntuaciones disponibles por dimensión; cada dimensión conserva por separado la nota docente, la nota AMV y el método aplicado.</p>
              <div class="summary-grid">
                <div class="metric"><span>Promedio integral</span><strong>{{ integratedAverage }}</strong><small>Escala 1–10 · {{ integratedStatus === 'complete' ? 'completa' : integratedStatus === 'partial' ? 'parcial' : 'pendiente' }}</small></div>
                <div class="metric"><span>Dimensiones con resultado</span><strong>{{ integratedDimensionsCount }}/8</strong><small>Fuentes disponibles por dimensión</small></div>
              </div>
              <div v-if="completedDimensions === 8" class="recommendation">
                <strong>Próximo paso pedagógico</strong>
                <p>{{ derivedNextStep }}</p>
              </div>
              <div class="report-actions">
                <button class="primary" type="button" :disabled="completedDimensions !== 8" @click="exportEvaluationPdf">⤓ Generar informe PDF</button>
                <span class="muted">Abre un informe imprimible. En el diálogo del navegador elige «Guardar como PDF».</span>
              </div>
            </section>
          </template>
        </template>
      </section>
    </section>
    <footer>AMV Vocal Engine · Combinación 50/50 solo cuando ambas fuentes son válidas · Fuentes originales conservadas.</footer>
  </main>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { fetchStudents } from '@/services/studentService'
import {
  fetchVocalRecordings,
  uploadVocalRecording,
  requestVocalAnalysis,
  fetchVocalRecordingById,
  createVocalRecordingSignedUrl,
  updateVocalRecordingMetadata,
  deleteVocalRecording
} from '@/services/vocalIntelligenceService'
import {
  AMV_DIMENSIONS,
  fetchTeacherEvaluation,
  saveTeacherEvaluation as persistTeacherEvaluation
} from '@/services/vocalTeacherEvaluationService'

const dimensions = AMV_DIMENSIONS
const students = ref([])
const selectedStudent = ref(null)
const selectedStudentId = ref(null)
const recordings = ref([])
const activeRecording = ref(null)
const activeRecordingId = ref(null)
const search = ref('')
const loadingStudents = ref(false)
const loadingRecordings = ref(false)
const showNewAudition = ref(false)
const editingRecordingId = ref(null)
const editForm = reactive({ title: '', song: '' })
const busy = ref(false)
const error = ref('')
const message = ref('')
const proposalMessage = ref('')
const loadingAudio = ref(false)
const scores = reactive(Object.fromEntries(dimensions.map(d => [d.key, null])))
const observations = ref('')
const strengths = ref('')
const priorities = ref('')
const exercisePlan = ref('')
const pollingRecordingIds = new Set()
const form = reactive({ title: '', song: '', artist: '', songType: 'cover', key: '', audio: null, referenceFile: null, context: '' })

const filteredStudents = computed(() => students.value.filter(s => s.name.toLowerCase().includes(search.value.toLowerCase())))
const completedDimensions = computed(() => dimensions.filter(d => Number.isInteger(scores[d.key]) && scores[d.key] >= 1 && scores[d.key] <= 10).length)
const teacherAverage = computed(() => completedDimensions.value ? (dimensions.reduce((sum, d) => sum + (Number(scores[d.key]) || 0), 0) / completedDimensions.value).toFixed(2) : '—')
// El motor solo puede aportar evidencia automática a afinación y ritmo.
// No se asignan notas automáticas a aire, fonación, registro, resonancia,
// dicción o expresión: esas dimensiones requieren evaluación docente.
const AUTOMATIC_DIMENSIONS = new Set(['intonation', 'rhythm'])
const acousticScores = computed(() => {
  const analysis = activeRecording.value?.analysis
  const payload = analysis?.workerResult || analysis?.worker_result || analysis
  const status = String(analysis?.status || payload?.status || '').toLowerCase()
  const ready = ['completed', 'complete', 'succeeded', 'success', 'done'].includes(status)
  const raw = payload?.dimensions || analysis?.dimensions || payload?.profile?.dimensions || payload?.result?.dimensions || {}
  const aliases = {
    intonation: ['intonation', 'afinacion', 'pitch_accuracy', 'pitchAccuracy'],
    rhythm: ['rhythm', 'ritmo', 'rhythmic_precision', 'rhythmicPrecision']
  }

  // Si el motor informa calidad de alineación, exigimos confianza y cobertura
  // mínimas. Si no entrega esos metadatos, nunca inventamos valores: solo
  // aceptamos una puntuación explícita 1–10 ya guardada por el adaptador.
  const alignment = payload?.alignment || payload?.alignment_v3 || payload?.alignmentMetrics ||
    payload?.alignment_metrics || payload?.metrics?.alignment || analysis?.alignment || {}
  const ambiguous = alignment?.ambiguous === true || alignment?.is_ambiguous === true ||
    alignment?.isAmbiguous === true || payload?.alignment_ambiguous === true
  const eligible = alignment?.eligible ?? alignment?.score_eligible ?? alignment?.scoreEligible ??
    payload?.alignment_eligible ?? payload?.score_eligible
  const readRatio = (...values) => {
    const value = values.find(v => v != null && v !== '')
    if (value == null) return null
    const n = Number(value)
    if (!Number.isFinite(n)) return null
    return n > 1 && n <= 100 ? n / 100 : n
  }
  const confidence = readRatio(alignment?.confidence, alignment?.alignment_confidence,
    alignment?.alignmentConfidence, payload?.alignment_confidence, payload?.alignmentConfidence)
  const coverage = readRatio(alignment?.coverage, alignment?.alignment_coverage,
    alignment?.alignmentCoverage, payload?.alignment_coverage, payload?.alignmentCoverage)
  const alignmentValid = !ambiguous && eligible !== false &&
    (confidence == null || confidence >= 0.60) &&
    (coverage == null || coverage >= 0.35)

  return Object.fromEntries(dimensions.map(d => {
    if (!AUTOMATIC_DIMENSIONS.has(d.key)) return [d.key, null]
    const entry = aliases[d.key]?.map(k => raw?.[k]).find(v => v != null)
    const candidate = typeof entry === 'number'
      ? entry
      : entry?.score10 ?? entry?.score_10 ?? entry?.score ?? entry?.value
    const value = candidate == null || candidate === '' ? NaN : Number(candidate)
    const valid = ready && alignmentValid && Number.isFinite(value) && value >= 1 && value <= 10
    return [d.key, valid ? Number(value.toFixed(2)) : null]
  }))
})
// Extrae las métricas técnicas del formato real de AMV 3.2.x.
// Importante: los porcentajes de scoring NO son notas en escala 1–10.
const acousticMetrics = computed(() => {
  const analysis = activeRecording.value?.analysis
  if (!analysis) return null
  const payload = analysis.workerResult || analysis.worker_result || analysis
  const scoring = payload.scoring || payload.result?.scoring || payload.comparison?.scoring || {}
  const intonation = scoring.intonation || {}
  const melodic = scoring.melodic_accuracy || scoring.melodicAccuracy || {}
  const percent = value => {
    const n = Number(value)
    return value != null && value !== '' && Number.isFinite(n) && n >= 0 && n <= 100 ? n : null
  }
  const result = {
    intonation: percent(intonation.score ?? scoring.score),
    melodicAccuracy: percent(melodic.score),
    within25: percent(intonation.within_25_cents_percent ?? intonation.within25CentsPercent),
    within50: percent(intonation.within_50_cents_percent ?? intonation.within50CentsPercent),
    within100: percent(intonation.within_100_cents_percent ?? intonation.within100CentsPercent),
    matchedEvents: Number.isFinite(Number(scoring.matched_events ?? scoring.matchedEvents)) ? Number(scoring.matched_events ?? scoring.matchedEvents) : null,
    excludedOctaves: Number.isFinite(Number(intonation.excluded_confirmed_octave_events ?? intonation.excludedConfirmedOctaveEvents)) ? Number(intonation.excluded_confirmed_octave_events ?? intonation.excludedConfirmedOctaveEvents) : null
  }
  return Object.values(result).some(value => value != null) ? result : null
})
function formatPercent(value) {
  return value == null ? '—' : `${Number(value).toLocaleString('es-CL', { maximumFractionDigits: 2 })}%`
}

const integratedScores = computed(() => Object.fromEntries(dimensions.map(d => {
  const rawTeacher = scores[d.key]
  const teacher = Number.isInteger(Number(rawTeacher)) && Number(rawTeacher) >= 1 && Number(rawTeacher) <= 10
    ? Number(rawTeacher)
    : null
  const acoustic = acousticScores.value[d.key]
  // 50/50 únicamente cuando hay dos notas válidas de la misma dimensión.
  return [d.key, teacher != null && acoustic != null
    ? Number(((teacher + acoustic) / 2).toFixed(2))
    : teacher ?? acoustic]
})))
const integratedDimensionsCount = computed(() => dimensions.filter(d => integratedScores.value[d.key] != null).length)
const integratedStatus = computed(() => {
  if (!integratedDimensionsCount.value) return 'pending'
  // La evaluación está completa cuando el docente puntuó las ocho dimensiones.
  // La falta de una métrica automática no convierte la evaluación docente en parcial.
  return completedDimensions.value === dimensions.length ? 'complete' : 'partial'
})
const integratedAverage = computed(() => {
  const values = dimensions.map(d => integratedScores.value[d.key]).filter(v => Number.isFinite(v))
  return values.length ? (values.reduce((a, b) => a + b, 0) / values.length).toFixed(1) : '—'
})
const integratedRadarPolygon = computed(() => dimensions.filter(d => integratedScores.value[d.key] != null).map(d => {
  const p = integratedRadarPoint(dimensions.findIndex(x => x.key === d.key), integratedScores.value[d.key])
  return `${p.x},${p.y}`
}).join(' '))

const radarScorePolygon = computed(() => dimensions.map((dimension, index) => {
  const point = radarPoint(index, Number(scores[dimension.key]))
  return `${point.x},${point.y}`
}).join(' '))
const analysisStatus = computed(() => {
  const analysis = activeRecording.value?.analysis
  if (!analysis) return null
  const payload = analysis.workerResult || analysis.worker_result || analysis
  const status = String(analysis.status || payload.status || '').toLowerCase()
  if (['completed', 'complete', 'succeeded', 'success', 'done', 'usable_for_comparison'].includes(status)) {
    return { tone: 'done', title: 'Análisis completado', description: payload.summary || 'El motor informa que terminó el procesamiento. Revisa las dimensiones disponibles antes de usarlas como evidencia.' }
  }
  if (['failed', 'error'].includes(status)) {
    return { tone: 'error', title: 'El análisis tuvo un error', description: payload.errorMessage || payload.error_message || payload.summary || 'Revisa el detalle técnico e intenta solicitar el análisis nuevamente.' }
  }
  return { tone: 'pending', title: 'Análisis pendiente o en proceso', description: payload.summary || 'Hay un registro de análisis, pero todavía no existe un resultado completado para interpretar.' }
})
const derivedNextStep = computed(() => {
  const weakest = [...dimensions].filter(d => scores[d.key] != null).sort((a, b) => scores[a.key] - scores[b.key])[0]
  if (!weakest) return 'Completa la pauta docente.'
  return `Prioriza ${weakest.label.toLowerCase()} en la próxima clase. Define un ejercicio concreto y vuelve a observar esta dimensión en la siguiente audición.`
})

onMounted(loadStudents)

async function loadStudents() {
  loadingStudents.value = true
  error.value = ''
  try { students.value = await fetchStudents() }
  catch (e) { error.value = readableError(e, 'No se pudieron cargar los alumnos.') }
  finally { loadingStudents.value = false }
}

async function selectStudent(student) {
  selectedStudent.value = student
  selectedStudentId.value = student.id
  activeRecording.value = null
  activeRecordingId.value = null
  showNewAudition.value = false
  resetEvaluation()
  await loadRecordings()
}

async function loadRecordings() {
  if (!selectedStudentId.value) return
  loadingRecordings.value = true
  error.value = ''
  try {
    recordings.value = await fetchVocalRecordings(selectedStudentId.value)
    if (recordings.value.length && !activeRecordingId.value) await selectRecording(recordings.value[0])
  } catch (e) { error.value = readableError(e, 'No se pudo cargar el historial de audiciones.') }
  finally { loadingRecordings.value = false }
}

async function selectRecording(recording) {
  activeRecording.value = recording
  activeRecordingId.value = recording.id
  resetEvaluation()
  error.value = ''
  // El resultado puede terminar mientras el profesor está trabajando.
  await loadActiveAudio()
  try {
    const saved = await fetchTeacherEvaluation(recording.id)
    if (saved) {
      for (const d of dimensions) scores[d.key] = saved.scores?.[d.key] == null ? null : Number(saved.scores[d.key])
      observations.value = saved.observations || ''
      strengths.value = saved.strengths || ''
      priorities.value = saved.priorities || ''
      exercisePlan.value = saved.exercise_plan || ''
      proposalMessage.value = ''
    }
  } catch (e) {
    error.value = readableError(e, 'No se pudo recuperar la evaluación docente. Revisa la migración y las políticas RLS.')
  }

  // Solo consulta el estado existente; nunca solicita otro análisis.
  if (isAnalysisPending(recording)) void pollAnalysisUntilTerminal(recording.id)
}

function startEditingRecording(recording) {
  editingRecordingId.value = recording.id
  editForm.title = recording.title || ''
  editForm.song = recording.song || ''
  error.value = ''
  message.value = ''
}

function cancelEditingRecording() {
  editingRecordingId.value = null
  editForm.title = ''
  editForm.song = ''
}

async function saveRecordingMetadata() {
  if (editingRecordingId.value == null) return
  const recording = recordings.value.find(item => String(item.id) === String(editingRecordingId.value))
  if (!recording) {
    error.value = 'No se encontró la audición que intentas editar. Actualiza el historial.'
    cancelEditingRecording()
    return
  }

  busy.value = true
  error.value = ''
  message.value = ''
  try {
    const updated = await updateVocalRecordingMetadata(recording.id, {
      title: editForm.title,
      song: editForm.song
    })
    recordings.value = recordings.value.map(item =>
      String(item.id) === String(recording.id) ? { ...item, ...updated, audioUrl: item.audioUrl || updated.audioUrl || '' } : item
    )
    if (String(activeRecordingId.value) === String(recording.id)) {
      activeRecording.value = { ...activeRecording.value, ...updated, audioUrl: activeRecording.value?.audioUrl || updated.audioUrl || '' }
    }
    cancelEditingRecording()
    message.value = 'Datos de la audición actualizados.'
  } catch (e) {
    error.value = readableError(e, 'No se pudieron guardar los cambios de la audición.')
  } finally {
    busy.value = false
  }
}

async function removeRecording(recording) {
  const title = recording.title || recording.song || 'esta audición'
  const confirmed = window.confirm(
    `¿Eliminar definitivamente "${title}"?\n\nSe borrará el registro y su audio almacenado. Los análisis vinculados también se eliminarán si la base de datos aplica la relación ON DELETE CASCADE. Esta acción no se puede deshacer.`
  )
  if (!confirmed) return

  busy.value = true
  error.value = ''
  message.value = ''
  try {
    await deleteVocalRecording(recording)
    recordings.value = recordings.value.filter(item => String(item.id) !== String(recording.id))
    if (String(activeRecordingId.value) === String(recording.id)) {
      activeRecording.value = null
      activeRecordingId.value = null
      resetEvaluation()
    }
    if (String(editingRecordingId.value) === String(recording.id)) cancelEditingRecording()
    message.value = 'Audición eliminada.'
    await loadRecordings()
  } catch (e) {
    error.value = readableError(e, 'No se pudo eliminar la audición. El audio o el registro podrían seguir existiendo.')
  } finally {
    busy.value = false
  }
}

async function createAudition() {
  if (!selectedStudentId.value) return
  if (!form.audio || !form.referenceFile) {
    error.value = 'Selecciona el audio del alumno y el archivo de referencia.'
    return
  }

  busy.value = true
  error.value = ''
  message.value = ''

  try {
    // Primero guarda ambos archivos y crea el registro de la audición.
    const recording = await uploadVocalRecording({
      studentId: selectedStudentId.value,
      file: form.audio,
      referenceFile: form.referenceFile,
      title: form.title,
      song: form.song,
      artist: form.artist,
      songType: form.songType,
      key: form.key,
      recordedAt: new Date().toISOString()
    })

    // Limpiar el formulario después de guardar evita duplicar la audición si
    // el worker tarda en terminar. La referencia se envía una sola vez.
    form.title = ''
    form.song = ''
    form.artist = ''
    form.key = ''
    form.audio = null
    form.referenceFile = null
    form.context = ''
    showNewAudition.value = false

    await loadRecordings()
    const fresh = await fetchVocalRecordingById(recording.id)
    await selectRecording(fresh)

    try {
      const queued = await requestVocalAnalysis(recording.id)
      message.value = queued?.queued
        ? 'Audición guardada. AMV está procesando la comparación; puedes completar la evaluación docente mientras llegan los resultados.'
        : 'Audición guardada y solicitud enviada a AMV.'
      // La Edge Function responde al encolar; el worker trabaja en segundo
      // plano. Consultamos la misma grabación, sin volver a invocar la función.
      void pollAnalysisUntilTerminal(recording.id)
    } catch (requestError) {
      error.value = `La audición quedó guardada, pero no se pudo iniciar el análisis AMV: ${readableError(requestError, 'Error al solicitar el análisis.')}`
      message.value = 'La audición y sus archivos quedaron guardados. Revisa el mensaje de error antes de volver a intentarlo.'
    }

    // Actualiza la ficha sin volver a subir ni volver a encolar la audición.
    const updated = await fetchVocalRecordingById(recording.id)
    if (String(activeRecordingId.value) === String(recording.id)) {
      activeRecording.value = { ...updated, audioUrl: activeRecording.value?.audioUrl || updated.audioUrl || '' }
    }
    recordings.value = recordings.value.map(item =>
      String(item.id) === String(recording.id)
        ? { ...updated, audioUrl: item.audioUrl || updated.audioUrl || '' }
        : item
    )
  } catch (e) {
    error.value = readableError(e, 'No se pudo guardar la audición. Comprueba el audio, la referencia y los permisos de almacenamiento.')
  } finally {
    busy.value = false
  }
}

async function loadActiveAudio() {
  if (!activeRecording.value) return
  if (activeRecording.value.audioUrl) return
  const recording = activeRecording.value
  const storagePath = recording.storagePath || recording.storage_path || recording.audioPath || recording.audio_path
  if (!storagePath) return
  loadingAudio.value = true
  try {
    const audioUrl = await createVocalRecordingSignedUrl(storagePath)
    if (String(activeRecordingId.value) === String(recording.id)) {
      activeRecording.value = { ...recording, audioUrl }
      recordings.value = recordings.value.map(item => String(item.id) === String(recording.id) ? { ...item, audioUrl } : item)
    }
  } catch (e) {
    console.warn('[AMV] No se pudo generar URL firmada para el audio:', e)
  } finally {
    loadingAudio.value = false
  }
}

function integratedRadarPoint(index, value) {
  const angle = (-Math.PI / 2) + (index * Math.PI * 2 / dimensions.length)
  const radius = Math.max(0, Math.min(10, Number(value) || 0)) * 15.5
  return { x: Number((230 + Math.cos(angle) * radius).toFixed(2)), y: Number((194 + Math.sin(angle) * radius).toFixed(2)) }
}
function integratedRadarGrid(level) {
  return dimensions.map((_, index) => {
    const point = integratedRadarPoint(index, level)
    return `${point.x},${point.y}`
  }).join(' ')
}
function radarPoint(index, value) {
  const angle = (-Math.PI / 2) + (index * Math.PI * 2 / dimensions.length)
  const radius = Math.max(0, Math.min(10, Number(value) || 0)) * 15.5
  return { x: Number((230 + Math.cos(angle) * radius).toFixed(2)), y: Number((194 + Math.sin(angle) * radius).toFixed(2)) }
}
function radarGrid(level) {
  return dimensions.map((_, index) => {
    const point = radarPoint(index, level)
    return `${point.x},${point.y}`
  }).join(' ')
}
function radarLabel(index) {
  const point = radarPoint(index, 10.65)
  return { x: point.x, y: point.y, anchor: point.x < 195 ? 'end' : point.x > 265 ? 'start' : 'middle' }
}
function shortDimensionLabel(label) {
  const labels = {
    'Ritmo y precisión': 'Ritmo',
    'Aire y fraseo': 'Aire y fraseo',
    'Fonación y emisión': 'Fonación',
    'Registro y transiciones': 'Registro',
    'Resonancia y timbre': 'Resonancia',
    'Dicción y articulación': 'Dicción',
    'Expresión y musicalidad': 'Expresión'
  }
  return labels[label] || label
}
function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]))
}
