/* Acciones seguras para administrar audiciones sin anidar botones. */
.recording-row { display:flex; align-items:stretch; gap:10px; padding:8px; border:1px solid #e6e8ef; border-radius:13px; margin:8px 0; background:#fff; }
.recording-row.active { border-color:#c77a98; background:#fff8fb; box-shadow:0 0 0 2px rgba(184,15,75,.06); }
.recording-select { display:flex; align-items:center; gap:12px; flex:1; min-width:0; padding:5px; border:0; background:transparent; text-align:left; cursor:pointer; color:inherit; }
.recording-select .record-copy { flex:1; min-width:0; }
.recording-actions { display:flex; align-items:center; gap:6px; flex-shrink:0; }
.compact { padding:8px 11px; font-size:12px; }
.danger { border:1px solid #efc7cc; border-radius:9px; padding:10px 13px; background:#fff2f3; color:#a52d3a; font-weight:700; cursor:pointer; }
.danger:hover { background:#ffe5e8; }
.danger:disabled { opacity:.55; cursor:not-allowed; }
.edit-recording-form { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:14px; margin-top:18px; padding:18px; border:1px solid #e9c5d2; border-radius:14px; background:#fff9fb; }
.edit-recording-form .section-heading, .edit-recording-form .form-actions, .edit-recording-form > .muted { grid-column:1/-1; }
.edit-recording-form h3 { margin:0; }
.edit-recording-form label { display:grid; gap:7px; font-size:12px; font-weight:700; }
@media(max-width:640px) {
  .recording-row { flex-direction:column; }
  .recording-select { align-items:flex-start; }
  .recording-actions { justify-content:flex-end; }
  .edit-recording-form { grid-template-columns:1fr; }
}



