}

function analysisStatusKey(recording) {
  const analysis = recording?.analysis
  const payload = analysis?.workerResult || analysis?.worker_result || analysis
  return String(analysis?.status || payload?.status || '').toLowerCase()
}

function isAnalysisPending(recording) {
  if (!recording?.analysis) return false
  return !['completed', 'complete', 'succeeded', 'success', 'done', 'usable_for_comparison', 'failed', 'error'].includes(analysisStatusKey(recording))
}

async function refreshAnalysisStatus() {
  if (!activeRecording.value) return
  const recordingId = activeRecording.value.id
  busy.value = true
  error.value = ''
  try {
    const fresh = await fetchVocalRecordingById(recordingId)
    if (String(activeRecordingId.value) === String(recordingId)) {
      activeRecording.value = { ...fresh, audioUrl: activeRecording.value?.audioUrl || fresh.audioUrl || '' }
    }
    recordings.value = recordings.value.map(item =>
      String(item.id) === String(recordingId)
        ? { ...fresh, audioUrl: item.audioUrl || fresh.audioUrl || '' }
        : item
    )
    const status = analysisStatusKey(fresh)
    if (['completed', 'complete', 'succeeded', 'success', 'done', 'usable_for_comparison'].includes(status)) {
      message.value = 'Análisis AMV completado. Ya puedes revisar la evidencia y finalizar tu evaluación docente.'
    } else if (['failed', 'error'].includes(status)) {
      error.value = fresh.analysis?.errorMessage || 'AMV registró un error de procesamiento. Revisa el detalle técnico.'
    } else {
      message.value = 'El análisis sigue en cola o procesándose. El panel seguirá consultando el resultado sin volver a encolar el trabajo.'
      void pollAnalysisUntilTerminal(recordingId)
    }
  } catch (e) {
    error.value = readableError(e, 'No se pudo actualizar el estado del análisis.')
  } finally {
    busy.value = false
  }
}

async function pollAnalysisUntilTerminal(recordingId, maxAttempts = 90, intervalMs = 4000) {
  const key = String(recordingId)
  if (pollingRecordingIds.has(key)) return
  pollingRecordingIds.add(key)
  try {
    for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, intervalMs))
      const fresh = await fetchVocalRecordingById(recordingId)
      const status = analysisStatusKey(fresh)
      const previous = recordings.value.find(item => String(item.id) === key)
      const merged = { ...fresh, audioUrl: previous?.audioUrl || (String(activeRecordingId.value) === key ? activeRecording.value?.audioUrl : '') || fresh.audioUrl || '' }
      recordings.value = recordings.value.map(item => String(item.id) === key ? merged : item)
      if (String(activeRecordingId.value) === key) activeRecording.value = merged

      if (['completed', 'complete', 'succeeded', 'success', 'done'].includes(status)) {
        if (String(activeRecordingId.value) === key) {
          message.value = 'Análisis AMV completado. Ya puedes revisar la evidencia y finalizar tu evaluación docente.'
        }
        return
      }
      if (['failed', 'error'].includes(status)) {
        if (String(activeRecordingId.value) === key) {
          error.value = fresh.analysis?.errorMessage || 'AMV registró un error de procesamiento. Revisa el detalle técnico.'
        }
        return
      }
      if (!fresh.analysis) return
    }
    if (String(activeRecordingId.value) === key) {
      message.value = 'AMV sigue procesando esta audición. Puedes continuar con tu pauta docente y usar “Actualizar estado” más tarde.'
    }
  } catch (e) {
    console.warn('[AMV] No se pudo consultar el estado del análisis:', e)
  } finally {
    pollingRecordingIds.delete(key)
  }
}

function setScore(key, value) {
  scores[key] = Number(value)
  proposalMessage.value = ''
}

function generatePedagogicalProposal() {
  if (completedDimensions.value !== 8) {
    proposalMessage.value = 'Completa las ocho puntuaciones para generar una propuesta pedagógica.'
    return
  }

  const ordered = [...dimensions].sort((a, b) => Number(scores[a.key]) - Number(scores[b.key]))
  const strong = ordered.filter(d => Number(scores[d.key]) >= 8)
  const priority = ordered.filter(d => Number(scores[d.key]) <= 4)
  const developing = ordered.filter(d => Number(scores[d.key]) >= 5 && Number(scores[d.key]) <= 7)
  const focus = (priority.length ? priority : developing.length ? developing : [ordered[0]]).slice(0, 1)
  const scoreLabel = d => `${d.label}: ${Number(scores[d.key])}/10`
  const song = activeRecording.value?.song || activeRecording.value?.title || 'la canción que estás preparando'

  const studentLanguage = {
    intonation: {
      what: 'Vamos a practicar cómo encontrar una nota y mantenerla con comodidad. No necesitas cantar fuerte: lo importante es escuchar, probar y comparar.',
