}
async function saveEvaluation() {
  if (!activeRecording.value) return
  if (completedDimensions.value !== 8) { error.value = 'Evalúa las ocho dimensiones antes de guardar.'; return }
  busy.value = true; error.value = ''; message.value = ''
  try {
    await persistTeacherEvaluation({
      recordingId: activeRecording.value.id,
      studentId: selectedStudentId.value,
      scores: Object.fromEntries(dimensions.map(d => [d.key, Number(scores[d.key])])),
      observations: observations.value,
      strengths: strengths.value,
      priorities: priorities.value,
      exercisePlan: exercisePlan.value,
      integratedResult: { status: 'teacher_only_until_rules_validated', note: 'Las evidencias automáticas se mantienen separadas hasta validar reglas de combinación por dimensión.' }
    })
    message.value = 'Evaluación docente guardada correctamente.'
  } catch (e) { error.value = readableError(e, 'No se pudo guardar. Revisa la migración y las políticas de acceso.') }
  finally { busy.value = false }
}

function resetEvaluation() {
  for (const d of dimensions) scores[d.key] = null
  observations.value = ''; strengths.value = ''; priorities.value = ''; exercisePlan.value = ''; proposalMessage.value = ''
}
function recordingAnalysisLabel(recording) {
  const analysis = recording?.analysis
  if (!analysis) return 'Sin análisis'
  const payload = analysis.workerResult || analysis.worker_result || analysis
  const status = String(analysis.status || payload.status || '').toLowerCase()
  if (['completed', 'complete', 'succeeded', 'success', 'done', 'usable_for_comparison'].includes(status)) return 'Completado'
  if (['failed', 'error'].includes(status)) return 'Error'
  return 'En proceso'
}
function recordingAnalysisTone(recording) {
  const label = recordingAnalysisLabel(recording)
  if (label === 'Completado') return 'done'
  if (label === 'Error') return 'error'
  return 'pending'
}
function initials(name) { return String(name || '?').split(/\s+/).slice(0, 2).map(part => part[0] || '').join('').toUpperCase() }
function voiceTone(voice) {
  const value = String(voice || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  if (value.includes('soprano')) return 'voice-soprano'
  if (value.includes('alto') || value.includes('contralto')) return 'voice-alto'
  if (value.includes('tenor')) return 'voice-tenor'
  if (value.includes('bajo') || value.includes('bass')) return 'voice-bajo'
  return 'voice-unclassified'
}
function formatDate(value) { if (!value) return 'Fecha sin registrar'; const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Fecha sin registrar' : new Intl.DateTimeFormat('es-CL', { dateStyle: 'medium' }).format(date) }
function readableError(e, fallback) { return e?.message || fallback }
</script>

